WITH session_summary AS (SELECT session_id, COUNT(DISTINCT duration_sec) AS unique_event_types, COUNT(*) AS num_web_events FROM web_events WHERE HOUR(event_time) BETWEEN 6 AND 14 GROUP BY session_id) SELECT s.id, s.browser, s.country, ss.unique_event_types, ss.num_web_events FROM sessions s INNER JOIN session_summary ss ON s.id = ss.session_id WHERE ss.num_web_events >= 4 ORDER BY s.browser;
